CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused kernel: MaxPool3d(k=2,s=2) -> MaxPool3d(k=3,s=3) -> sum(dim=1, keepdim=True)
// Input:  [N, C, D,  H,  W]  contiguous float32
// Output: [N, 1, D2, H2, W2]
// Launch: one block per output voxel (n, d2, h2, w2)
//         blockDim.x = BLOCK_C (power-of-2 >= C, capped at 128)
// Each thread handles one or more channels, computes the composed 2x2x2 -> 3x3x3 max,
// then threads reduce their partial sums via shared memory.

#define FUSED_BLOCK_C 64

__global__ void fused_pool_pool_sum_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int D,  int H,  int W,
    int D1, int H1, int W1,
    int D2, int H2, int W2
) {
    // Block index encodes (n, d2, h2, w2)
    int vox = blockIdx.x;  // linear voxel index
    int total_vox = N * D2 * H2 * W2;
    if (vox >= total_vox) return;

    int w2 = vox % W2; int tmp = vox / W2;
    int h2 = tmp % H2;     tmp = tmp / H2;
    int d2 = tmp % D2;     tmp = tmp / D2;
    int n  = tmp;

    int tid = threadIdx.x;  // channel index

    // Shared memory for block-level channel reduction
    __shared__ float smem[FUSED_BLOCK_C];

    float partial = 0.0f;

    // Each thread processes channels: tid, tid+blockDim.x, ...
    for (int c = tid; c < C; c += blockDim.x) {
        long nc_offset = ((long)n * C + c) * (long)(D * H * W);

        // pool2 base in pool1 space
        int d1_base = d2 * 3;
        int h1_base = h2 * 3;
        int w1_base = w2 * 3;

        float p2_max = -3.402823466e+38f;

        for (int kd1 = 0; kd1 < 3; kd1++) {
            int d1 = d1_base + kd1;
            if (d1 >= D1) continue;
            int d_base = d1 * 2;

            for (int kh1 = 0; kh1 < 3; kh1++) {
                int h1 = h1_base + kh1;
                if (h1 >= H1) continue;
                int h_base = h1 * 2;

                for (int kw1 = 0; kw1 < 3; kw1++) {
                    int w1 = w1_base + kw1;
                    if (w1 >= W1) continue;
                    int w_base = w1 * 2;

                    float p1_max = -3.402823466e+38f;
                    for (int id = 0; id < 2; id++) {
                        int di = d_base + id;
                        if (di >= D) continue;
                        for (int ih = 0; ih < 2; ih++) {
                            int hi = h_base + ih;
                            if (hi >= H) continue;
                            for (int iw = 0; iw < 2; iw++) {
                                int wi = w_base + iw;
                                if (wi >= W) continue;
                                float val = __ldg(input + nc_offset + (long)(di * H * W + hi * W + wi));
                                p1_max = fmaxf(p1_max, val);
                            }
                        }
                    }
                    p2_max = fmaxf(p2_max, p1_max);
                }
            }
        }
        partial += p2_max;
    }

    // Store partial sum in shared memory
    smem[tid] = partial;
    __syncthreads();

    // Tree reduction in shared memory
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smem[tid] += smem[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        long out_idx = ((long)n * D2 + d2) * (long)(H2 * W2) + (long)(h2 * W2 + w2);
        output[out_idx] = smem[0];
    }
}

torch::Tensor fused_pool_pool_sum_cuda(torch::Tensor x) {
    int N = x.size(0), C = x.size(1);
    int D = x.size(2), H = x.size(3), W = x.size(4);

    // MaxPool3d(k=2, s=2): floor division
    int D1 = D / 2, H1 = H / 2, W1 = W / 2;
