// For output element (od, oh, ow) and filter tap (kd, kh, kw):
//   nd = od + pad - kd = od + 2 - kd   must be divisible by stride=2
//   id = nd / 2  in [0, Din)
// ---------------------------------------------------------------------------

// Tile: each block handles a tile of (TILE_CO) output channels and one output voxel.
// Grid: (N * OD * OH * OW,  Cout / TILE_CO)
#define CT_TILE_CO 8
#define CT_BLOCK_SIZE 128

__global__ void convtranspose3d_fwd_kernel(
    const float* __restrict__ input,   // [N, Cin, Din, Hin, Win]
