                int h1 = h1_base + kh1;
                if (h1 >= H1) continue;
                int h_base = h1 * 2;
                for (int kw1 = 0; kw1 < 3; kw1++) {
                    int w1 = w1_base + kw1;
                    if (w1 >= W1) continue;
                    int w_base = w1 * 2;
                    float p1_max = -3.402823466e+38f;
                    #pragma unroll
                    for (int id = 0; id < 2; id++) {
                        int di = d_base + id;
                        if (di >= D) continue;
                        #pragma unroll
                        for (int ih = 0; ih < 2; ih++) {
