// Specialized ConvTranspose3d forward
// Parameters fixed to benchmark regime: stride=2, padding=2, kernel_size=5,
// dilation=1, groups=1, bias present.
// weight layout: [Cin, Cout, kD, kH, kW]  (PyTorch ConvTranspose3d convention)
// Output size per dim: (Din - 1) * 2 - 2*2 + 5 = Din*2 - 2
// Each thread computes one output element (n, co, od, oh, ow).
// ---------------------------------------------------------------------------
__global__ void convtranspose3d_p78_kernel(
    const float* __restrict__ input,   // [N, Cin, Din, Hin, Win]
    const float* __restrict__ weight,  // [Cin, Cout, kD, kH, kW]
    const float* __restrict__ bias,    // [Cout]
    float* __restrict__ output,        // [N, Cout, Dout, Hout, Wout]
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Dout, int Hout, int Wout
) {
    // grid: (Dout*Hout*Wout, Cout, N)  blockDim.x threads handle spatial chunks
    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int co = blockIdx.y;
    int n  = blockIdx.z;

    int spatial_total = Dout * Hout * Wout;
    if (spatial_idx >= spatial_total) return;

    int ow = spatial_idx % Wout; int tmp2 = spatial_idx / Wout;
    int oh = tmp2 % Hout;
    int od = tmp2 / Hout;

    // ConvTranspose3d with stride=2, padding=2, kernel=5:
    // output[od] = sum over ci, kd: input[ci, (od+2-kd)/2, ...] if (od+2-kd) % 2 == 0
    float acc = __ldg(bias + co);

    int input_stride_n   = Cin * Din * Hin * Win;
    int input_stride_c   = Din * Hin * Win;
    int input_stride_d   = Hin * Win;
    int input_stride_h   = Win;

    // weight[ci, co, kd, kh, kw]: stride = Cout*5*5*5, 5*5*5, 5*5, 5, 1
    int weight_stride_ci = Cout * 5 * 5 * 5;
    int weight_stride_co = 5 * 5 * 5;
    int weight_stride_kd = 5 * 5;
    int weight_stride_kh = 5;

    const float* inp_n = input  + (long)n * input_stride_n;
    const float* w_co  = weight + co * weight_stride_co;

    for (int ci = 0; ci < Cin; ci++) {
        const float* inp_nc = inp_n + ci * input_stride_c;
        const float* w_ci   = w_co  + ci * weight_stride_ci;

        #pragma unroll
        for (int kd = 0; kd < 5; kd++) {
            int td = od + 2 - kd;  // padding=2
            if (td < 0 || (td & 1)) continue;
            int id = td >> 1;
            if (id >= Din) continue;

            #pragma unroll
            for (int kh = 0; kh < 5; kh++) {
                int th = oh + 2 - kh;
                if (th < 0 || (th & 1)) continue;
                int ih = th >> 1;
                if (ih >= Hin) continue;

                #pragma unroll
                for (int kw = 0; kw < 5; kw++) {
                    int tw = ow + 2 - kw;
                    if (tw < 0 || (tw & 1)) continue;
                    int iw = tw >> 1;
                    if (iw >= Win) continue;

                    float iv = __ldg(inp_nc + id * input_stride_d + ih * input_stride_h + iw);
                    float wv = __ldg(w_ci   + kd * weight_stride_kd + kh * weight_stride_kh + kw);
                    acc += iv * wv;
                }
            }
