torch::Tensor convtranspose3d_p78_forward_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {

    int N    = input.size(0);
    int Cin  = input.size(1);
    int Din  = input.size(2);
    int Hin  = input.size(3);
    int Win  = input.size(4);
