    int Dout = (Din - 1) * 2 - 2 * 2 + 5;
    int Hout = (Hin - 1) * 2 - 2 * 2 + 5;
    int Wout = (Win - 1) * 2 - 2 * 2 + 5;

    auto output = torch::empty({N, Cout, Dout, Hout, Wout}, input.options());

    int spatial_total = Dout * Hout * Wout;
    int threads = 128;
    dim3 block(threads);
    dim3 grid((spatial_total + threads - 1) / threads, Cout, N);

    convtranspose3d_p78_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, Cout,
        Din, Hin, Win,
        Dout, Hout, Wout
    );

    return output;
}
