                                if (wi >= W) continue;
                                float val = __ldg(input + nc_offset + (long)(di * H * W + hi * W + wi));
                                p1_max = fmaxf(p1_max, val);
                            }
                        }
                    }
                    p2_max = fmaxf(p2_max, p1_max);
                }
            }
