# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// ---------------------------------------------------------------------------
// Shared-memory staged fused tail:
//   MaxPool3d(k=2,s=2) -> MaxPool3d(k=3,s=3) -> sum over channels
// Input:  [N, C, D,  H,  W]  contiguous float32
// Output: [N, 1, D2, H2, W2]
//
// Each block handles one output voxel (n, d2, h2, w2).
// blockDim.x threads cooperatively load the composed input tile [C, 6, 6, 6]
// into shared memory (using -FLT_MAX for out-of-bounds), then thread 0
// performs the full fused max/sum reduction from SMEM.
// ---------------------------------------------------------------------------
__global__ void fused_pool_pool_sum_smem_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int D,  int H,  int W,
    int D1, int H1, int W1,
    int D2, int H2, int W2
) {
    // Each block owns one output voxel
    int voxel_idx = blockIdx.x;
    int total = N * D2 * H2 * W2;
    if (voxel_idx >= total) return;

    int w2 = voxel_idx % W2;  int tmp = voxel_idx / W2;
    int h2 = tmp % H2;         tmp = tmp / H2;
    int d2 = tmp % D2;         tmp = tmp / D2;
    int n  = tmp;

    // In input space, each output voxel maps to a 6x6x6 window
    // (pool2 stride=3 * pool1 stride=2 = 6; pool2 k=3 * pool1 k=2 = 6)
    int d_start = d2 * 6;
    int h_start = h2 * 6;
    int w_start = w2 * 6;

    // Shared memory: [C][6][6][6] = C*216 floats
    extern __shared__ float smem[];  // size = C * 216 * sizeof(float)

    int tid = threadIdx.x;
    int block_threads = blockDim.x;
    int tile_size = C * 216;  // C * 6*6*6

    // Cooperative load: each thread loads a strided subset of the tile
    for (int i = tid; i < tile_size; i += block_threads) {
        int c   = i / 216;
        int rem = i % 216;
        int td  = rem / 36;
        int th  = (rem % 36) / 6;
        int tw  = rem % 6;

        int di = d_start + td;
        int hi = h_start + th;
        int wi = w_start + tw;

        float val = -FLT_MAX;
        if (di < D && hi < H && wi < W) {
            long nc_off = ((long)n * C + c) * (long)(D * H * W);
            val = __ldg(input + nc_off + (long)(di * H * W + hi * W + wi));
        }
        smem[i] = val;
    }
    __syncthreads();

    // Only thread 0 computes the reduction
    if (tid != 0) return;

    float channel_sum = 0.0f;

    for (int c = 0; c < C; c++) {
        // smem layout: [c][td][th][tw] = c*216 + td*36 + th*6 + tw
        int c_off = c * 216;

        // pool2: 3x3x3 window over pool1 space
        // pool1: 2x2x2 window over input space
        // In tile coords: pool1 cell (kd1,kh1,kw1) covers td in [kd1*2, kd1*2+1]
        float p2_max = -FLT_MAX;

        for (int kd1 = 0; kd1 < 3; kd1++) {
            // Check pool1 cell validity in original space
            int d1 = d2 * 3 + kd1;
            if (d1 >= D1) continue;

            for (int kh1 = 0; kh1 < 3; kh1++) {
                int h1 = h2 * 3 + kh1;
                if (h1 >= H1) continue;

                for (int kw1 = 0; kw1 < 3; kw1++) {
                    int w1 = w2 * 3 + kw1;
                    if (w1 >= W1) continue;

                    // pool1 2x2x2 window in tile coords
                    float p1_max = -FLT_MAX;
                    #pragma unroll
                    for (int id = 0; id < 2; id++) {
                        int td = kd1 * 2 + id;
                        // boundary in original space already guarded by smem load
                        #pragma unroll
                        for (int ih = 0; ih < 2; ih++) {
                            int th = kh1 * 2 + ih;
                            #pragma unroll
                            for (int iw = 0; iw < 2; iw++) {
                                int tw = kw1 * 2 + iw;
                                float v = smem[c_off + td * 36 + th * 6 + tw];
                                p1_max = fmaxf(p1_max, v);
                            }
                        }
                    }
                    p2_max = fmaxf(p2_max, p1_max);
                }
            }
