        // propagating -inf; however semantically an empty window shouldn't
        // occur for valid pool2 cells, so add it directly.
        channel_sum += p2_max;
    }

    long out_idx = ((long)n * D2 + d2) * (long)(H2 * W2) + (long)(h2 * W2 + w2);
    output[out_idx] = channel_sum;
}

// Fallback scalar kernel (no shared memory) for edge cases
__global__ void fused_pool_pool_sum_scalar_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C,
    int D,  int H,  int W,
    int D1, int H1, int W1,
    int D2, int H2, int W2
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * D2 * H2 * W2;
    if (idx >= total) return;

    int w2 = idx % W2; int tmp = idx / W2;
    int h2 = tmp % H2;     tmp = tmp / H2;
    int d2 = tmp % D2;     tmp = tmp / D2;
    int n  = tmp;

    int d1_base = d2 * 3;
    int h1_base = h2 * 3;
    int w1_base = w2 * 3;

    float channel_sum = 0.0f;

    for (int c = 0; c < C; c++) {
        long nc_offset = ((long)n * C + c) * (long)(D * H * W);
        float p2_max = -FLT_MAX;

        for (int kd1 = 0; kd1 < 3; kd1++) {
            int d1 = d1_base + kd1;
            if (d1 >= D1) continue;
            int d_base = d1 * 2;
            for (int kh1 = 0; kh1 < 3; kh1++) {
                int h1 = h1_base + kh1;
                if (h1 >= H1) continue;
                int h_base = h1 * 2;
                for (int kw1 = 0; kw1 < 3; kw1++) {
                    int w1 = w1_base + kw1;
                    if (w1 >= W1) continue;
                    int w_base = w1 * 2;
                    float p1_max = -FLT_MAX;
                    #pragma unroll
                    for (int id = 0; id < 2; id++) {
                        int di = d_base + id;
                        if (di >= D) continue;
                        #pragma unroll
                        for (int ih = 0; ih < 2; ih++) {
                            int hi = h_base + ih;
                            if (hi >= H) continue;
                            #pragma unroll
                            for (int iw = 0; iw < 2; iw++) {
                                int wi = w_base + iw;
                                if (wi >= W) continue;
                                float val = __ldg(input + nc_offset + (long)(di * H * W + hi * W + wi));
                                p1_max = fmaxf(p1_max, val);
                            }
                        }
                    }
                    p2_max = fmaxf(p2_max, p1_max);
                }
            }
        }
        channel_sum += p2_max;
    }

    long out_idx = ((long)n * D2 + d2) * (long)(H2 * W2) + (long)(h2 * W2 + w2);
    output[out_idx] = channel_sum;
}

torch::Tensor fused_pool_pool_sum_cuda(torch::Tensor x) {
    int N = x.size(0), C = x.size(1);
    int D = x.size(2), H = x.size(3), W = x.size(4);
    int D1 = D / 2, H1 = H / 2, W1 = W / 2;
    int D2 = D1 / 3, H2 = H1 / 3, W2 = W1 / 3;

    auto output = torch::zeros({N, 1, D2, H2, W2}, x.options());
    int total = N * D2 * H2 * W2;
    if (total == 0) return output;

    // Check if shared memory variant fits: C * 216 * 4 bytes
    size_t smem_bytes = (size_t)C * 216 * sizeof(float);

    // Query max shared memory per block
    int device;
    cudaGetDevice(&device);
    size_t max_smem;
    cudaDeviceGetAttribute((int*)&max_smem,
        cudaDevAttrMaxSharedMemoryPerBlock, device);
    // safe cast: attribute is int bytes
    cudaDeviceGetAttribute((int*)&max_smem,
        cudaDevAttrMaxSharedMemoryPerBlock, device);

    if (smem_bytes <= 48 * 1024 && C <= 256) {
        // SMEM-staged kernel: one block per voxel, 64 threads for cooperative load
        int block_threads = 64;
        // Ensure tile_size is evenly distributed among threads for good utilization
        // tile_size = C*216; for C=64: 13824 elements, 64 threads -> 216 each
        int blocks = total;
        fused_pool_pool_sum_smem_kernel<<<blocks, block_threads, smem_bytes>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            N, C, D, H, W,
            D1, H1, W1,
            D2, H2, W2
        );
    } else {
        // Fallback scalar kernel
        int threads = 256;
        int blocks = (total + threads - 1) / threads;
        fused_pool_pool_sum_scalar_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            N, C, D, H, W,
            D1, H1, W1,
            D2, H2, W2
        );
    }

    return output;
}
